class Stack:
    def __init__(self):
        self._data = []

    def push(self, value):
        self._data.append(value)

    def pop(self):
        if not self._data:
            raise IndexError('empty')
        return self._data.pop()

    def peek(self):
        if not self._data:
            raise IndexError('empty')
        return self._data[-1]

    def __len__(self):
        return len(self._data)

