from collections import deque

class Queue:
    def __init__(self):
        self._data = deque()

    def enqueue(self, value):
        self._data.append(value)

    def dequeue(self):
        if not self._data:
            raise IndexError('empty')
        return self._data.popleft()

    def __len__(self):
        return len(self._data)

