def reverse_list(items):
    stack = list(items)
    out = []
    while stack:
        out.append(stack.pop())
    return out

from collections import deque

def moving_average(values, k):
    window = deque()
    total = 0
    result = []
    for v in values:
        window.append(v)
        total += v
        if len(window) > k:
            total -= window.popleft()
        if len(window) == k:
            result.append(total / k)
    return result
